class Fone:
    def __init__(self, id: str, number: str):
        self.__id: str = id
        self.__number: str = number

    def isValid(self):
        em = "0123456789()."
        return all(c in em for c in self.__number)

    def getId(self):
        return self.__id

    def getNumber(self):
        return self.__number

    def __str__(self):
        return f"{self.__id}:{self.__number}"

